package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.saveddata.SavedData;import java.util.*;
/** Persistent local index and deferred removal tombstones, without chunk tickets. */
public final class Pb01WorldData extends SavedData{
 public static final class Entry{public final UUID id;public final BlockPos root;public final Direction face;boolean removed;Entry(UUID i,BlockPos p,Direction f,boolean r){id=i;root=p.immutable();face=f;removed=r;}}
 private final Map<UUID,Entry>entries=new HashMap<>();private final Map<Long,Set<UUID>>chunks=new HashMap<>();public static Pb01WorldData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(Pb01WorldData::load,Pb01WorldData::new,"sbw_pb01_bunkers");}
 public void add(Pb01BlockEntity b){if(entries.containsKey(b.id))return;var e=new Entry(b.id,b.getBlockPos(),b.facing(),false);entries.put(e.id,e);index(e);setDirty();}private void index(Entry e){for(var p:Pb01Geometry.MODEL.all(e.root,e.face))chunks.computeIfAbsent(new ChunkPos(p).toLong(),k->new HashSet<>()).add(e.id);}
 public List<Entry>near(int x0,int z0,int x1,int z1){var ids=new HashSet<UUID>();for(int x=x0;x<=x1;x++)for(int z=z0;z<=z1;z++)ids.addAll(chunks.getOrDefault(ChunkPos.asLong(x,z),Set.of()));var out=new ArrayList<Entry>();for(var id:ids){var e=entries.get(id);if(e!=null&&!e.removed)out.add(e);}return out;}
 public void removeAt(ServerLevel l,BlockPos p){for(var e:List.copyOf(entries.values()))if(e.root.equals(p)){removed(l,e.id);return;}}public void removed(ServerLevel l,UUID id){var e=entries.get(id);if(e==null)return;e.removed=true;setDirty();clean(l,e);}
 public void chunk(ServerLevel l,long key){for(var id:List.copyOf(chunks.getOrDefault(key,Set.of()))){var e=entries.get(id);if(e==null)continue;if(!e.removed&&l.hasChunkAt(e.root)&&!(l.getBlockState(e.root).getBlock()instanceof Pb01Block)){e.removed=true;setDirty();}if(e.removed)clean(l,e);else if(l.hasChunkAt(e.root)&&l.getBlockEntity(e.root)instanceof Pb01BlockEntity b&&b.id.equals(e.id))b.checkSupport();}}
 private void clean(ServerLevel l,Entry e){if(l.hasChunkAt(e.root)&&l.getBlockEntity(e.root)instanceof Pb01BlockEntity b&&!b.removing){if(!b.id.equals(e.id)){erase(e);return;}b.remove(null,false,true);return;}boolean pending=false,old=Pb01Block.MUTATING.get();Pb01Block.MUTATING.set(true);try{for(var p:Pb01Geometry.MODEL.all(e.root,e.face)){if(!l.hasChunkAt(p)){pending=true;continue;}if(l.getBlockEntity(p)instanceof Dvt01BlockEntity d&&e.id.equals(d.pbBunker)){Pb01Dvt.dropAndRemove(d,null,true);continue;}var s=l.getBlockState(p);if(s.getBlock()instanceof Pb01Block&&Pb01Block.root(p,s).equals(e.root))l.removeBlock(p,false);}}finally{Pb01Block.MUTATING.set(old);}if(!pending)erase(e);}
 private void erase(Entry e){entries.remove(e.id);for(var it=chunks.values().iterator();it.hasNext();){var v=it.next();v.remove(e.id);if(v.isEmpty())it.remove();}setDirty();}
 public static Pb01WorldData load(CompoundTag n){var d=new Pb01WorldData();for(var v:n.getList("Bunkers",10)){var a=(CompoundTag)v;var e=new Entry(a.getUUID("Id"),BlockPos.of(a.getLong("Root")),Direction.from2DDataValue(a.getInt("Facing")),a.getBoolean("Removed"));d.entries.put(e.id,e);d.index(e);}return d;}
 @Override public CompoundTag save(CompoundTag n){var a=new ListTag();for(var e:entries.values()){var v=new CompoundTag();v.putUUID("Id",e.id);v.putLong("Root",e.root.asLong());v.putInt("Facing",e.face.get2DDataValue());v.putBoolean("Removed",e.removed);a.add(v);}n.put("Bunkers",a);return n;}
}
